async function callLLM(model, messages){
  const t0 = performance.now();
  const res = await llm.chat({ model, messages });
  const t1 = performance.now();
  const meta = { latencyMs: t1-t0, inTokens: res.usage?.prompt_tokens, outTokens: res.usage?.completion_tokens };
  console.log('[llm]', model, meta);
  return res;
}
